verification.expression:
let
  flake = builtins.getFlake "path:/home/brittonr/git/onix-core";
  names = [ "aspen1" "aspen2" "aspen3" "bonsai" "britton-desktop" "britton-fw" ];
in builtins.listToAttrs (map (name: let c = flake.nixosConfigurations.${name}.config; in {
  inherit name;
  value = {
    builders = map (builder: builder.hostName) c.nix.buildMachines;
    grpcEnabled = c.programs.nix-grpc-store.enable or false;
    clientCredentialDeclared = builtins.hasAttr "nix-build-farm-client" c.clan.core.vars.generators;
    accessRules = c.services.nix-grpc-daemon.accessRules or [];
    ingressNames = c.networking.hosts."100.100.103.95" or [];
  };
}) names)
